import type { Metadata } from "next";
import { db } from "@/lib/db";
import { UseCaseLanding, type UseCaseContent } from "@/components/marketing/UseCaseLanding";

export const dynamic = "force-dynamic";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Docker Hosting — One-Click Docker VPS, Full Root, NVMe",
  description:
    "Run Docker and Docker Compose on a fast NVMe VPS with full root, a one-click Docker image, dedicated IPv4, daily backups, and DDoS protection. From $6.49/mo.",
  alternates: { canonical: "/docker-hosting" },
  openGraph: {
    type: "article",
    title: "Docker Hosting — One-Click Docker VPS, Full Root, NVMe",
    description:
      "A developer-grade Docker VPS: one-click Docker Engine, full root, NVMe on ZFS, dedicated IP, backups and DDoS protection.",
    url: `${APP_URL}/docker-hosting`,
  },
};

const content: UseCaseContent = {
  eyebrow: "Docker hosting",
  title: "Docker hosting on a",
  highlight: "real VPS",
  sub: "Your own NVMe server with full root and the Docker Engine ready on first boot. Spin up containers, compose stacks, and expose ports on a dedicated IP, from $6.49/mo.",
  intro: [
    "Docker needs a real Linux kernel and root — the two things shared hosting won't give you. A VPS hands you the whole machine: dedicated CPU and NVMe, your own public IPv4, and unrestricted control over the Docker daemon, networking, and volumes. Bind whatever ports you like and run as many containers as your RAM allows.",
    "Nxeon ships a one-click Docker image that boots with Docker Engine and the Compose plugin already installed and enabled, so you skip the apt dance and go straight to `docker compose up`. Everything runs on enterprise NVMe over a self-healing ZFS mirror, so image pulls, layer writes, and container I/O stay fast even when you're building.",
    "It's the clean, predictable base you want for a container host: full SSH, a real firewall you control, instant snapshots before a risky deploy, and one-click resize when a stack outgrows its box — no rebuild, no migration.",
  ],
  whyTitle: "Built for Docker",
  why: [
    { title: "One-click Docker Engine", body: "Choose the Docker image and your server boots with Docker Engine and the Compose plugin installed and running — no manual setup before your first container." },
    { title: "Full root, real kernel", body: "SSH in as root on a genuine Linux VM. Manage the daemon, tune networking, mount volumes, and run privileged containers — it's your machine, not a sandbox." },
    { title: "NVMe on ZFS", body: "Enterprise NVMe SSD on a mirrored, self-healing ZFS pool means fast image pulls, quick layer writes, and snappy container I/O under load." },
    { title: "Dedicated IPv4 + IPv6 ready", body: "A dedicated public IPv4 to publish container ports and reverse-proxy your services, plus IPv6 readiness for modern stacks." },
    { title: "Snapshots before deploys", body: "Take an instant snapshot before pulling a new image or reshaping a Compose stack — roll back in seconds if a release goes sideways." },
    { title: "DDoS protection + firewall", body: "Always-on network DDoS mitigation and a managed firewall keep your exposed services online when they draw attention." },
  ],
  steps: [
    { title: "Create your account", body: "Sign up with no credit card required and open the deploy wizard." },
    { title: "Pick Docker + a plan", body: "Select the one-click Docker image and a plan sized to your containers, then deploy — it's live in under a minute with Docker already running." },
    { title: "SSH in and compose", body: "Connect over SSH (or the noVNC web console), drop in your docker-compose.yml, and run `docker compose up -d`." },
    { title: "Publish and monitor", body: "Point a domain at your dedicated IP, expose your ports, and watch CPU, RAM, and network in real-time metrics from the dashboard." },
  ],
  specNote:
    "A 2 GB Starter comfortably runs a handful of lightweight containers. Reach for Standard (4 GB) or Pro (8 GB) for heavier stacks — databases, queues, several services in one Compose file — and resize vCPU, RAM, and disk any time without a rebuild.",
  faq: [
    { q: "Is Docker really preinstalled?", a: "Yes. Pick the one-click Docker image and your VPS boots with Docker Engine and the Compose plugin installed and enabled. SSH in and your first `docker run` or `docker compose up` works immediately." },
    { q: "Can I run Docker Compose and multi-container stacks?", a: "Absolutely. You have full root on a real Linux VM, so you can run Compose, build images, mount volumes, create custom networks, and run as many containers as your RAM allows." },
    { q: "Which plan do I need for Docker?", a: "It depends on your containers. A 2 GB Starter handles a few lightweight services; pick Standard (4 GB) or Pro (8 GB) for databases, queues, or several services at once. You can resize any time — no rebuild." },
    { q: "Can I expose container ports to the internet?", a: "Yes. Every plan includes a dedicated IPv4, so you can publish ports and put a reverse proxy (like Nginx, Traefik, or Caddy) in front of your containers. The managed firewall lets you control what's open." },
    { q: "Do I get backups and snapshots?", a: "Yes. Automatic daily backups plus instant snapshots are included, so you can snapshot before a risky deploy and roll back in seconds. DDoS protection and a dedicated IP are included too." },
  ],
  related: [
    { label: "VPS hosting", href: "/vps" },
    { label: "n8n hosting", href: "/n8n-hosting" },
    { label: "Node.js hosting", href: "/nodejs-hosting" },
    { label: "Pricing", href: "/pricing" },
    { label: "Free tools", href: "/tools" },
  ],
};

export default async function DockerHostingPage() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  return <UseCaseLanding content={content} plans={plans} />;
}

